def translate(source,language='ru'):
    if language not in ('en','de','es'): return source
    for prefix,versions in MESSAGES.items():
        if prefix.endswith(': ') and source.startswith(prefix): return versions[('en','de','es').index(language)]+source[len(prefix):]
    return MESSAGES.get(source,(source,source,source))[('en','de','es').index(language)]
